-- === TABLES ===

BEGIN;

CREATE TABLE IF NOT EXISTS advocacy_letter_templates (
	id SERIAL NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	subject_line VARCHAR(500) NOT NULL, 
	body_template TEXT NOT NULL, 
	target_level VARCHAR(20) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_advocacy_letter_templates_id ON advocacy_letter_templates (id);

CREATE TABLE IF NOT EXISTS aed_locations (
	id SERIAL NOT NULL, 
	branch_id INTEGER NOT NULL, 
	location_description VARCHAR(200) NOT NULL, 
	room_number VARCHAR(50), 
	floor VARCHAR(50), 
	latitude FLOAT, 
	longitude FLOAT, 
	access_instructions TEXT, 
	visible_signage BOOLEAN, 
	directional_signage BOOLEAN, 
	last_inspection_date TIMESTAMP WITH TIME ZONE, 
	battery_installed TIMESTAMP WITH TIME ZONE, 
	pads_installed TIMESTAMP WITH TIME ZONE, 
	in_service BOOLEAN, 
	PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_aed_locations_id ON aed_locations (id);
CREATE INDEX IF NOT EXISTS ix_aed_locations_in_service ON aed_locations (in_service);
CREATE INDEX IF NOT EXISTS ix_aed_locations_branch_id ON aed_locations (branch_id);

CREATE TABLE IF NOT EXISTS ai_model_allowlist (
	id SERIAL NOT NULL, 
	model_name VARCHAR(100) NOT NULL, 
	display_name VARCHAR(100), 
	description TEXT, 
	max_tokens_limit INTEGER NOT NULL, 
	allowed_temperature_min FLOAT NOT NULL, 
	allowed_temperature_max FLOAT NOT NULL, 
	enabled BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (model_name)
);

CREATE INDEX IF NOT EXISTS ix_ai_model_allowlist_id ON ai_model_allowlist (id);

CREATE TABLE IF NOT EXISTS ai_usage_limits (
	id SERIAL NOT NULL, 
	role VARCHAR(50) NOT NULL, 
	daily_limit INTEGER NOT NULL, 
	hourly_limit INTEGER NOT NULL, 
	max_tokens_per_request INTEGER NOT NULL, 
	enabled BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (role)
);

CREATE INDEX IF NOT EXISTS ix_ai_usage_limits_id ON ai_usage_limits (id);

CREATE TABLE IF NOT EXISTS alert_thresholds (
	id SERIAL NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	description TEXT, 
	category VARCHAR(50) NOT NULL, 
	threshold_type VARCHAR(50), 
	warning_level INTEGER, 
	critical_level INTEGER, 
	time_window_minutes INTEGER, 
	enabled BOOLEAN, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	PRIMARY KEY (id)
);

CREATE UNIQUE INDEX IF NOT EXISTS ix_alert_thresholds_name ON alert_thresholds (name);
CREATE INDEX IF NOT EXISTS ix_alert_thresholds_id ON alert_thresholds (id);

CREATE TABLE IF NOT EXISTS annual_report_validation_rules (
	id SERIAL NOT NULL, 
	state_code VARCHAR(2), 
	field_name VARCHAR(100) NOT NULL, 
	rule_type VARCHAR(50) NOT NULL, 
	description TEXT, 
	rule_value VARCHAR(500), 
	error_message VARCHAR(500) NOT NULL, 
	depends_on_field VARCHAR(100), 
	depends_on_operator VARCHAR(20), 
	depends_on_value VARCHAR(200), 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_annual_report_validation_rules_id ON annual_report_validation_rules (id);

CREATE TABLE IF NOT EXISTS anonymous_incident_patterns (
	id SERIAL NOT NULL, 
	incident_type VARCHAR(17) NOT NULL, 
	location VARCHAR(200), 
	date_start TIMESTAMP WITH TIME ZONE NOT NULL, 
	date_end TIMESTAMP WITH TIME ZONE NOT NULL, 
	report_count INTEGER NOT NULL, 
	average_severity VARCHAR(50), 
	pattern_summary TEXT, 
	recommended_actions TEXT, 
	PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_anonymous_incident_patterns_id ON anonymous_incident_patterns (id);
CREATE INDEX IF NOT EXISTS ix_anonymous_incident_patterns_incident_type ON anonymous_incident_patterns (incident_type);
CREATE INDEX IF NOT EXISTS ix_anonymous_incident_patterns_location ON anonymous_incident_patterns (location);

CREATE TABLE IF NOT EXISTS attendance_trends (
	id SERIAL NOT NULL, 
	period_start DATE NOT NULL, 
	period_end DATE NOT NULL, 
	period_type VARCHAR(20) NOT NULL, 
	program_type VARCHAR(50), 
	audience VARCHAR(50), 
	branch_id INTEGER, 
	total_sessions INTEGER NOT NULL, 
	total_attendance INTEGER NOT NULL, 
	avg_attendance_per_session FLOAT NOT NULL, 
	total_walk_ins INTEGER NOT NULL, 
	total_repeat_attendees INTEGER NOT NULL, 
	total_new_attendees INTEGER NOT NULL, 
	total_cost NUMERIC(10, 2) NOT NULL, 
	cost_per_attendee NUMERIC(10, 2) NOT NULL, 
	age_distribution JSON, 
	method_distribution JSON, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_trends_period_type ON attendance_trends (period_type, period_start);
CREATE INDEX IF NOT EXISTS ix_attendance_trends_program_type ON attendance_trends (program_type);
CREATE INDEX IF NOT EXISTS ix_attendance_trends_branch_id ON attendance_trends (branch_id);
CREATE INDEX IF NOT EXISTS ix_trends_program_audience ON attendance_trends (program_type, audience);
CREATE INDEX IF NOT EXISTS ix_attendance_trends_audience ON attendance_trends (audience);
CREATE INDEX IF NOT EXISTS ix_attendance_trends_id ON attendance_trends (id);
CREATE INDEX IF NOT EXISTS ix_attendance_trends_period_start ON attendance_trends (period_start);
CREATE INDEX IF NOT EXISTS ix_attendance_trends_period_type ON attendance_trends (period_type);

CREATE TABLE IF NOT EXISTS audit_readiness_checklists (
	id SERIAL NOT NULL, 
	organization_id INTEGER NOT NULL, 
	audit_type VARCHAR(200) NOT NULL, 
	created_for_audit_date DATE, 
	checklist_created_date DATE NOT NULL, 
	checklist_last_updated_date DATE NOT NULL, 
	items JSONB, 
	items_complete INTEGER, 
	items_in_progress INTEGER, 
	items_not_ready INTEGER, 
	items_total INTEGER, 
	completion_percentage FLOAT, 
	overall_ready BOOLEAN, 
	documentation_complete BOOLEAN, 
	staff_informed BOOLEAN, 
	resources_allocated BOOLEAN, 
	auditor_name VARCHAR(200), 
	auditor_company VARCHAR(200), 
	audit_start_date DATE, 
	audit_end_date DATE, 
	audit_completed BOOLEAN, 
	audit_findings TEXT, 
	audit_report_file VARCHAR(500), 
	follow_up_items JSONB, 
	follow_up_complete BOOLEAN, 
	notes TEXT, 
	PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_audit_readiness_checklists_id ON audit_readiness_checklists (id);
CREATE INDEX IF NOT EXISTS ix_audit_org ON audit_readiness_checklists (organization_id);
CREATE INDEX IF NOT EXISTS ix_audit_readiness_checklists_organization_id ON audit_readiness_checklists (organization_id);
CREATE INDEX IF NOT EXISTS ix_audit_type ON audit_readiness_checklists (audit_type);
CREATE INDEX IF NOT EXISTS ix_audit_ready ON audit_readiness_checklists (overall_ready);

CREATE TABLE IF NOT EXISTS author_embeddings (
	id SERIAL NOT NULL, 
	author_name VARCHAR(255) NOT NULL, 
	author_name_normalized VARCHAR(255) NOT NULL, 
	embedding VECTOR(768), 
	embedding_model VARCHAR(100) NOT NULL, 
	book_count INTEGER NOT NULL, 
	source_collections JSON, 
	genres JSON, 
	subjects JSON, 
	is_generated BOOLEAN NOT NULL, 
	generated_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_author_embeddings_hnsw_cosine ON author_embeddings USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64);
CREATE INDEX IF NOT EXISTS ix_author_embeddings_is_generated ON author_embeddings (is_generated);
CREATE INDEX IF NOT EXISTS ix_author_embeddings_id ON author_embeddings (id);
CREATE INDEX IF NOT EXISTS ix_author_embeddings_author_name ON author_embeddings (author_name);
CREATE UNIQUE INDEX IF NOT EXISTS ix_author_embeddings_author_name_normalized ON author_embeddings (author_name_normalized);

CREATE TABLE IF NOT EXISTS bibframe_contributors (
	id SERIAL NOT NULL, 
	uri VARCHAR(500), 
	contributor_type VARCHAR(20) NOT NULL, 
	name VARCHAR(500) NOT NULL, 
	name_inverted VARCHAR(500), 
	name_sort VARCHAR(500), 
	given_name VARCHAR(255), 
	family_name VARCHAR(255), 
	birth_date VARCHAR(20), 
	death_date VARCHAR(20), 
	organization_type VARCHAR(100), 
	place VARCHAR(255), 
	alternate_names TEXT, 
	biography TEXT, 
	viaf_id VARCHAR(50), 
	lcnaf_id VARCHAR(50), 
	isni VARCHAR(20), 
	orcid VARCHAR(20), 
	wikidata_id VARCHAR(20), 
	linked_data JSONB, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_bibframe_contributors_uri UNIQUE (uri)
);

CREATE INDEX IF NOT EXISTS ix_bibframe_contributors_viaf ON bibframe_contributors (viaf_id);
CREATE INDEX IF NOT EXISTS ix_bibframe_contributors_uri ON bibframe_contributors (uri);
CREATE INDEX IF NOT EXISTS ix_bibframe_contributors_lcnaf_id ON bibframe_contributors (lcnaf_id);
CREATE INDEX IF NOT EXISTS ix_bibframe_contributors_name_type ON bibframe_contributors (name, contributor_type);

CREATE TABLE IF NOT EXISTS bibframe_subjects (
	id SERIAL NOT NULL, 
	uri VARCHAR(500), 
	subject_type VARCHAR(50) NOT NULL, 
	label VARCHAR(500) NOT NULL, 
	label_normalized VARCHAR(500), 
	broader_term VARCHAR(500), 
	narrower_terms TEXT, 
	related_terms TEXT, 
	source authoritysource, 
	source_id VARCHAR(100), 
	lcsh_id VARCHAR(50), 
	fast_id VARCHAR(20), 
	wikidata_id VARCHAR(20), 
	scope_note TEXT, 
	linked_data JSONB, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_bibframe_subjects_uri UNIQUE (uri)
);

CREATE INDEX IF NOT EXISTS ix_bibframe_subjects_label ON bibframe_subjects (label);
CREATE INDEX IF NOT EXISTS ix_bibframe_subjects_uri ON bibframe_subjects (uri);
CREATE INDEX IF NOT EXISTS ix_bibframe_subjects_id ON bibframe_subjects (id);

CREATE TABLE IF NOT EXISTS boundary_policies (
	id SERIAL NOT NULL, 
	organization_id INTEGER NOT NULL, 
	policy_name VARCHAR(255) NOT NULL, 
	policy_code VARCHAR(50), 
	policy_text TEXT NOT NULL, 
	applies_to_boundary_types JSON, 
	escalation_procedure TEXT, 
	appeal_procedure TEXT, 
	requires_director_approval BOOLEAN, 
	requires_board_approval BOOLEAN, 
	effective_date TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	last_reviewed_date TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_boundary_policies_organization_id ON boundary_policies (organization_id);
CREATE INDEX IF NOT EXISTS ix_boundary_policies_id ON boundary_policies (id);
CREATE UNIQUE INDEX IF NOT EXISTS ix_boundary_policies_policy_code ON boundary_policies (policy_code);

CREATE TABLE IF NOT EXISTS branch_statistics (
	id SERIAL NOT NULL, 
	branch_id INTEGER NOT NULL, 
	period_start DATE NOT NULL, 
	period_end DATE NOT NULL, 
	total_checkouts INTEGER, 
	total_renewals INTEGER, 
	total_checkins INTEGER, 
	total_holds_placed INTEGER, 
	total_holds_filled INTEGER, 
	items_owned INTEGER, 
	items_added INTEGER, 
	items_withdrawn INTEGER, 
	items_sent_to_other_branches INTEGER, 
