CREATE TABLE IF NOT EXISTS insurance_policies (
	id SERIAL NOT NULL, 
	organization_id INTEGER NOT NULL, 
	policy_type insurancetype NOT NULL, 
	policy_name VARCHAR(200) NOT NULL, 
	policy_number VARCHAR(100) NOT NULL, 
	provider_name VARCHAR(200) NOT NULL, 
	coverage_amount FLOAT NOT NULL, 
	deductible FLOAT NOT NULL, 
	effective_date DATE NOT NULL, 
	expiration_date DATE NOT NULL, 
	renewal_reminder_days_before INTEGER, 
	auto_renews BOOLEAN, 
	renewal_pending BOOLEAN, 
	renewal_quote_received BOOLEAN, 
	new_renewal_date DATE, 
	claims_filed INTEGER, 
	recent_claim_date DATE, 
	claims_notes TEXT, 
	policy_document VARCHAR(500), 
	certificate_of_insurance VARCHAR(500), 
	endorsements JSONB, 
	modifications TEXT, 
	broker_name VARCHAR(200), 
	broker_contact VARCHAR(200), 
	notes TEXT, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_insurance_policy_expiration_after_effective CHECK (expiration_date > effective_date), 
	CONSTRAINT ck_insurance_policy_coverage_non_negative CHECK (coverage_amount >= 0), 
	CONSTRAINT ck_insurance_policy_deductible_non_negative CHECK (deductible >= 0), 
	CONSTRAINT ck_insurance_policy_claims_filed_non_negative CHECK (claims_filed >= 0), 
	UNIQUE (policy_number)
);

