CREATE TABLE IF NOT EXISTS inventory_audits (
	id SERIAL NOT NULL, 
	name VARCHAR(255) NOT NULL, 
	description TEXT, 
	location_filter VARCHAR(100), 
	started_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	completed_at TIMESTAMP WITH TIME ZONE, 
	items_expected INTEGER, 
	items_found INTEGER, 
	items_missing INTEGER, 
	items_misplaced INTEGER, 
	created_by_id INTEGER, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_inventory_audit_completed_after_started CHECK (completed_at IS NULL OR completed_at >= started_at), 
	CONSTRAINT ck_inventory_audit_items_expected_non_negative CHECK (items_expected >= 0), 
	CONSTRAINT ck_inventory_audit_items_found_non_negative CHECK (items_found >= 0), 
	CONSTRAINT ck_inventory_audit_items_missing_non_negative CHECK (items_missing >= 0), 
	CONSTRAINT ck_inventory_audit_items_misplaced_non_negative CHECK (items_misplaced >= 0), 
	FOREIGN KEY(created_by_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS ix_inventory_audits_id ON inventory_audits (id);

