	priority jobpriority NOT NULL, 
	queue_position INTEGER, 
	project_name VARCHAR(200) NOT NULL, 
	project_description TEXT, 
	file_name VARCHAR(255), 
	file_path VARCHAR(500), 
	file_size_bytes INTEGER, 
