	supports_needed BOOLEAN NOT NULL, 
	estimated_print_time_minutes INTEGER, 
	estimated_material_grams NUMERIC(10, 2), 
	actual_print_time_minutes INTEGER, 
	actual_material_grams NUMERIC(10, 2), 
	estimated_cost NUMERIC(10, 2) NOT NULL, 
	actual_cost NUMERIC(10, 2), 
	material_cost NUMERIC(10, 2) NOT NULL, 
	machine_time_cost NUMERIC(10, 2) NOT NULL, 
	payment_status makerspacepaystatus NOT NULL, 
	payment_id INTEGER, 
	reviewed_by_id INTEGER, 
	reviewed_at TIMESTAMP WITH TIME ZONE, 
	review_notes TEXT, 
	rejection_reason TEXT, 
	started_at TIMESTAMP WITH TIME ZONE, 
	completed_at TIMESTAMP WITH TIME ZONE, 
