	superseded_by_resolution_id INTEGER, 
	superseded_date TIMESTAMP WITH TIME ZONE, 
	rescinded_date TIMESTAMP WITH TIME ZONE, 
	rescinded_by_motion_id INTEGER, 
	rescinded_reason TEXT, 
