CREATE TABLE IF NOT EXISTS item_lifecycle_events (
	id SERIAL NOT NULL, 
	item_copy_id INTEGER NOT NULL, 
	event_type VARCHAR(18) NOT NULL, 
	description TEXT, 
	event_metadata JSONB, 
	performed_by_id INTEGER, 
	related_checkout_id INTEGER, 
	related_po_id INTEGER, 
	related_audit_id INTEGER, 
	related_weeding_id INTEGER, 
	event_timestamp TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_lifecycle_weeding_events_require_weeding_id CHECK (
            (event_type NOT IN (
                'marked_for_weeding', 'weeding_approved',
                'weeding_rejected', 'weeded', 'disposed'
            ))
            OR related_weeding_id IS NOT NULL
            ), 
	FOREIGN KEY(item_copy_id) REFERENCES item_copies (id) ON DELETE CASCADE, 
	FOREIGN KEY(performed_by_id) REFERENCES users (id) ON DELETE SET NULL, 
	FOREIGN KEY(related_checkout_id) REFERENCES checkouts (id) ON DELETE SET NULL, 
	FOREIGN KEY(related_po_id) REFERENCES purchase_orders (id) ON DELETE SET NULL, 
	FOREIGN KEY(related_audit_id) REFERENCES inventory_audits (id) ON DELETE SET NULL, 
	FOREIGN KEY(related_weeding_id) REFERENCES weeding_candidates (id) ON DELETE SET NULL
);

