-- Vetting Pipeline: Enum value renames (2026-04-01)
ALTER TYPE ebooksubmissionstatus ADD VALUE IF NOT EXISTS 'automated_review';
ALTER TYPE ebooksubmissionstatus ADD VALUE IF NOT EXISTS 'returned';
ALTER TYPE ebooksubmissionstatus ADD VALUE IF NOT EXISTS 'declined';
UPDATE indie_ebooks SET submission_status = 'returned' WHERE submission_status = 'revision_requested';
UPDATE indie_ebooks SET submission_status = 'automated_review' WHERE submission_status = 'ai_review';
UPDATE indie_ebooks SET submission_status = 'declined' WHERE submission_status = 'rejected';

