-- OCLC Submission Queue (2026-04-01)
CREATE TABLE IF NOT EXISTS oclc_queue (
    id SERIAL PRIMARY KEY,
    ebook_id INTEGER NOT NULL REFERENCES indie_ebooks(id) ON DELETE CASCADE,
    marc_record_binary BYTEA,
    status VARCHAR(20) NOT NULL DEFAULT 'pending',
    queued_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    submitted_at TIMESTAMPTZ,
    oclc_number VARCHAR(20),
    error_message TEXT,
    retry_count INTEGER NOT NULL DEFAULT 0,
    UNIQUE(ebook_id)
);
CREATE INDEX IF NOT EXISTS ix_oclc_queue_status ON oclc_queue (status) WHERE status = 'pending';

